package gateway

import (
	"github.com/STRK-Solutions/Feather-Mesh/web_demo/internal/control"
	"github.com/STRK-Solutions/Feather-Mesh/web_demo/internal/pipeline"
	"html/template"
)

type page struct {
	Account              control.Account
	Accounts             []control.Account
	Workspace            *control.Workspace
	Workspaces           []workspacePage
	LifecycleState       string
	WarningAt            string
	RetentionNotified    string
	RetentionDeleteAfter string
	CSRF                 string
	Config               Config
	Policy               control.Policy
	Jobs                 []control.Job
	PipelineJobs         []pipeline.Status
	PipelineAvailable    bool
	BrokerStatus         BrokerStatus
}

var home = template.Must(template.New("home").Parse(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Feather Mesh</title><style>body{font:17px system-ui;max-width:65rem;margin:3rem auto;padding:0 1rem;color:#172c36}table{border-collapse:collapse;width:100%}td,th{padding:.7rem;text-align:left;border-bottom:1px solid #ccd}button{padding:.6rem;margin:.25rem}section{padding:1rem;background:#f4f7f8;margin:1rem 0}label{display:block;margin:.5rem}a{color:#064c7c}</style><h1>Feather Mesh</h1><p>{{.Account.Email}} · {{.Account.Role}}</p><section><h2>Demo status</h2><p>Model: {{.Config.Model}}</p>{{with .BrokerStatus}}{{if .Available}}<p>Current run allocation: {{.Allocated}} · spent: {{.Spent}} · reserved: {{.Reserved}} · unknown outcome: {{.Unknown}}</p><p>Budget alert level: {{.AlertPercent}}% · {{if .Paused}}Model requests paused{{else}}Model requests enabled{{end}} · active: {{.Active}} · queued: {{.Queued}}</p><p>Recording configured: {{if .Recording}}enabled{{else}}disabled{{end}}</p>{{else}}<p role="status">Live budget, queue and recording status unavailable.</p>{{end}}{{end}}<p>Workspaces are disposable. Research records and reviewed exports are retained separately.</p></section>{{if .Accounts}}<h2>Accounts</h2><p>Policy revision {{.Policy.Revision}}. New invitations stay pending until edge access and workspace setup are ready.</p><table><tr><th>Email</th><th>Role</th><th>Status</th><th>Access</th></tr>{{range .Accounts}}<tr><td>{{.Email}}</td><td>{{.Role}}</td><td>{{.Status}}</td><td><form method="post" action="/accounts/disable"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="account_id" value="{{.ID}}"><input type="hidden" name="auth_version" value="{{.AuthVersion}}"><button>Disable account</button></form></td></tr>{{end}}</table><h2>Invite an account</h2><form method="post" action="/accounts/invite"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Exact lowercase email <input name="email" type="email" required></label><label>Role <select name="role"><option value="user">User</option><option value="admin">Admin</option></select></label><button>Create pending account</button></form><h2>Health and jobs</h2><table><tr><th>Job</th><th>State</th><th>Detail</th></tr>{{range .Jobs}}<tr><td>{{.ID}}</td><td>{{.Status}}</td><td>{{.Error}}</td></tr>{{end}}</table><h2>Dataset pipeline</h2>{{if .PipelineAvailable}}<table><tr><th>Job</th><th>Bundle</th><th>State</th></tr>{{range .PipelineJobs}}<tr><td><a href="/pipeline/review/{{.ID}}">{{.ID}}</a></td><td>{{.Bundle}}</td><td>{{.State}}</td></tr>{{end}}</table>{{else}}<p>Pipeline status unavailable. Existing jobs and approvals remain recorded privately.</p>{{end}}<form method="post" action="/pipeline/plan"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Closed source job JSON <textarea name="job" rows="12" cols="70" maxlength="65536" required></textarea></label><button>Review bounded source job</button></form><h3>Prepare withdrawal</h3><p>Creates a new complete release with FEAM tombstones. The old release remains intact; promotion requires exact candidate approval and revokes its grants.</p><form method="post" action="/pipeline/withdrawal-plan"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Bundle <input name="bundle" required></label><label>Current release digest <input name="digest" pattern="[0-9a-f]{64}" required></label><label>Product <input name="product" required></label><label>Version <input name="version" required></label><label>Reason <input name="reason" maxlength="2000" required></label><button>Review withdrawal job</button></form><h2>Participant workspaces and datasets</h2><p>Dataset changes stop the workspace and close open terminals. The participant can start it again after the change completes.</p>{{range .Workspaces}}<section><h3>{{.OwnerEmail}}</h3><p>Generation {{.Generation}} · grant version {{.GrantVersion}} · {{if .Ready}}Ready{{else}}Stopped or reconfiguration pending{{end}}</p><form method="post" action="/workspace/action"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="workspace_id" value="{{.ID}}"><input type="hidden" name="generation" value="{{.Generation}}"><button name="action" value="workspace.stop">Stop</button><button name="action" value="workspace.reset">Review reset</button><button name="action" value="workspace.delete">Review delete</button></form>{{$owner := .OwnerID}}{{$version := .GrantVersion}}{{range .Grants}}<p>{{.Bundle}} · <code>{{.Digest}}</code></p><form method="post" action="/datasets/grant"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="account_id" value="{{$owner}}"><input type="hidden" name="grant_version" value="{{$version}}"><input type="hidden" name="bundle" value="{{.Bundle}}"><button name="action" value="revoke">Revoke dataset</button></form>{{else}}<p>No datasets assigned.</p>{{end}}<form method="post" action="/datasets/grant"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="account_id" value="{{.OwnerID}}"><input type="hidden" name="grant_version" value="{{.GrantVersion}}"><label>Bundle <input name="bundle" pattern="[a-z][a-z0-9-]{0,62}" required></label><label>Approved release digest <input name="digest" pattern="[0-9a-f]{64}" minlength="64" maxlength="64" required></label><button name="action" value="assign">Assign exact release</button></form></section>{{end}}<h2>Quotas</h2><p>Each workspace has a 2 GiB writable disk and two terminal connections. Runtime ceilings are operator approved. Administrators have no workspace by default.</p>{{else}}{{with .Workspace}}<h2>Your workspace</h2><p>Generation {{.Generation}} · {{$.LifecycleState}}</p>{{if $.WarningAt}}<p role="status">Idle warning: this workspace will stop after 30 minutes without activity. Return to the terminal and enter input to keep working.</p>{{end}}<p>{{if $.RetentionDeleteAfter}}<strong>Retention notice:</strong> This inactive workspace is eligible for deletion after {{$.RetentionDeleteAfter}} (UTC). Notice recorded {{$.RetentionNotified}}. Return to the terminal and enter input to resume activity before that deadline.</p>{{end}}<p>Idle stops preserve your files. Within a retained deployment, inactive workspace data is kept up to 30 days with advance warning before deletion. A confirmed reset, delete or deployment teardown may discard it earlier.</p>{{if and .Ready (eq $.LifecycleState "Running")}}<p><a href="https://{{.Hostname}}/">Open assisted FEAM</a></p>{{else}}<p>Start the workspace when setup or dataset reconfiguration has completed.</p>{{end}}<form method="post" action="/workspace/action"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="workspace_id" value="{{.ID}}"><input type="hidden" name="generation" value="{{.Generation}}"><button name="action" value="workspace.start">Start</button><button name="action" value="workspace.stop">Stop</button><button name="action" value="workspace.reset">Review reset</button><button name="action" value="workspace.delete">Review delete</button></form>{{else}}<p>No workspace is assigned to this account.</p>{{end}}{{end}}</html>`))
var review = template.Must(template.New("review").Parse(`<!doctype html><html lang="en"><meta charset="utf-8"><title>Confirm workspace change</title><h1>Confirm {{.Action}}</h1><p>This discards workspace files for {{.Workspace}}. Retained research records remain subject to their separate retention policy.</p><form method="post" action="/workspace/action"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="confirmation" value="{{.Confirmation}}"><button>Confirm this change</button></form><p><a href="/">Cancel</a></p></html>`))
